UPDATE public.courses
SET title = 'Artificial Intelligence',
    short_description = 'Learn Artificial Intelligence from fundamentals to real-world AI application development with Python, ML, deep learning, GenAI, LLMs, RAG, and agents.',
    full_description = 'Learn Artificial Intelligence from the fundamentals to building real-world AI applications. This 6-month program covers Python, data processing, mathematics, machine learning, deep learning, natural language processing, computer vision, generative AI, large language models, prompt engineering, AI APIs, AI agents, model deployment and end-to-end AI projects.',
    level = 'Beginner', duration = '6 Months | 24 Weeks', published_at = COALESCE(published_at, now())
WHERE slug = 'artificial-intelligence';

INSERT INTO public.course_weeks (course_id, week_number, month_number, title, topics, practical_task, assignment, mini_project, expected_outcome)
SELECT c.id, v.week_number, v.month_number, v.title, v.topics, v.practical_task, v.assignment, v.mini_project, v.expected_outcome
FROM public.courses c
CROSS JOIN (VALUES
(1,1,'Introduction to Artificial Intelligence',ARRAY['What is Artificial Intelligence?','AI vs Machine Learning vs Deep Learning','Types of AI','Narrow AI','General AI concepts','AI applications','AI in business','AI career opportunities','AI development lifecycle']::text[],'Identify real-world AI applications and design a simple AI solution.',NULL,NULL,'Explain AI fundamentals and identify practical AI opportunities.'),
(2,1,'Python for AI',ARRAY['Python introduction','Variables','Data types','Operators','Conditional statements','Loops','Functions','Lists','Tuples','Sets','Dictionaries']::text[],'Build Python programs for AI/data processing.',NULL,NULL,'Use Python fundamentals for AI and data workflows.'),
(3,1,'Advanced Python for AI',ARRAY['Object-oriented programming','Classes and objects','Modules','Packages','Exception handling','File handling','Lambda functions','List comprehensions','Virtual environments','Git/GitHub fundamentals']::text[],NULL,NULL,'Build a Python-based data processing application.','Build maintainable Python applications for AI projects.'),
(4,1,'NumPy, Pandas & Data Handling',ARRAY['NumPy arrays','Array operations','Pandas Series','DataFrames','CSV/Excel data','Filtering','Sorting','GroupBy','Data transformation','Basic data visualization']::text[],NULL,'Perform data analysis using Python.',NULL,'Load, transform, and analyze data for AI applications.'),
(5,2,'Mathematics for AI',ARRAY['Vectors','Matrices','Matrix operations','Functions','Derivatives','Probability fundamentals','Statistics fundamentals','Optimization concepts']::text[],'Implement mathematical operations using Python and NumPy.',NULL,NULL,'Understand the mathematics used by AI models.'),
(6,2,'Data Preprocessing',ARRAY['Data cleaning','Missing values','Duplicate data','Outliers','Encoding','Feature scaling','Normalization','Standardization','Train/test split']::text[],'Prepare a real-world dataset for AI modeling.',NULL,NULL,'Create clean, model-ready datasets.'),
(7,2,'Machine Learning Fundamentals',ARRAY['What is Machine Learning?','Supervised learning','Unsupervised learning','Reinforcement learning','Regression','Classification','Clustering','Model training','Model prediction']::text[],'Build a basic machine learning model.',NULL,NULL,'Explain core ML approaches and train a first model.'),
(8,2,'Machine Learning Algorithms',ARRAY['Linear Regression','Logistic Regression','KNN','Decision Trees','Random Forest','Support Vector Machines','K-Means','Model comparison']::text[],NULL,NULL,'Build a complete prediction/classification application.','Select and compare common machine learning algorithms.'),
(9,3,'Model Evaluation & Feature Engineering',ARRAY['Accuracy','Precision','Recall','F1-score','Confusion matrix','ROC-AUC','Cross-validation','Overfitting','Underfitting','Feature selection','Feature engineering']::text[],'Optimize and evaluate an ML model.',NULL,NULL,'Measure model quality and improve generalization.'),
(10,3,'Neural Networks',ARRAY['Neural network fundamentals','Artificial neurons','Layers','Activation functions','Forward propagation','Loss functions','Backpropagation','Gradient descent']::text[],'Build a basic neural network.',NULL,NULL,'Explain and train a basic neural network.'),
(11,3,'TensorFlow / PyTorch',ARRAY['Deep learning frameworks','Dataset preparation','Model creation','Training','Validation','Loss monitoring','Model evaluation','Saving trained models']::text[],NULL,'Build a neural network classification model.',NULL,'Train and save a deep learning model with a modern framework.'),
(12,3,'Computer Vision',ARRAY['Introduction to computer vision','Image processing','Image preprocessing','OpenCV fundamentals','CNNs','Convolution','Pooling','Image classification','Object detection concepts']::text[],NULL,NULL,'Build an image classification application.','Prepare image data and build a computer vision prototype.'),
(13,4,'Natural Language Processing',ARRAY['Introduction to NLP','Text preprocessing','Tokenization','Stop words','Stemming','Lemmatization','Text vectorization','TF-IDF']::text[],'Build a text classification system.',NULL,NULL,'Prepare text data and create a baseline NLP system.'),
(14,4,'Advanced NLP',ARRAY['Sentiment analysis','Text classification','Named Entity Recognition','Text similarity','Word embeddings','Introduction to transformers']::text[],NULL,'Build a sentiment analysis or text classification application.',NULL,'Apply modern NLP techniques to real text problems.'),
(15,4,'Generative AI Fundamentals',ARRAY['What is Generative AI?','Generative AI vs traditional AI','Large Language Models','Text generation','Image generation','Audio generation','Multimodal AI','AI APIs','Real-world Generative AI applications']::text[],'Build a basic Generative AI application using an API.',NULL,NULL,'Understand generative models and integrate an AI API.'),
(16,4,'Prompt Engineering',ARRAY['Prompt fundamentals','Zero-shot prompting','Few-shot prompting','Role prompting','Context engineering','Structured outputs','Prompt evaluation','AI limitations','Responsible AI','Hallucinations']::text[],NULL,NULL,'Build an AI-powered content/assistant application.','Create reliable prompts and evaluate responsible AI behavior.'),
(17,5,'Large Language Models',ARRAY['LLM architecture concepts','Transformers','Tokens','Embeddings','Context windows','Inference','LLM APIs','Model parameters','Temperature','System/user prompts']::text[],'Build an application using an LLM API.',NULL,NULL,'Use LLM APIs with controlled prompts and parameters.'),
(18,5,'Embeddings & Vector Databases',ARRAY['What are embeddings?','Semantic search','Vector databases','Similarity search','Document processing','Chunking','Retrieval']::text[],'Create a semantic document search system.',NULL,NULL,'Build semantic retrieval over a document collection.'),
(19,5,'Retrieval-Augmented Generation',ARRAY['What is RAG?','RAG architecture','Document ingestion','Chunking','Embeddings','Retrieval','Context injection','Answer generation','RAG evaluation']::text[],NULL,'Build a document-based AI chatbot.',NULL,'Connect retrieval and generation into a grounded AI assistant.'),
(20,5,'AI Agents',ARRAY['What are AI agents?','Agent architecture','Tools','Function calling','Memory concepts','Planning','Multi-step reasoning concepts','Agent workflows','Agent safety']::text[],NULL,NULL,'Build a simple AI agent that can use tools/APIs.','Design an agent workflow with tools and safety boundaries.'),
(21,6,'AI Application Development',ARRAY['AI application architecture','Frontend + AI backend','FastAPI/Flask','Connecting AI models to APIs','Authentication','Database integration','Logging','Error handling']::text[],'Build an AI-powered web application.',NULL,NULL,'Deliver an AI feature through a complete application architecture.'),
(22,6,'AI Deployment & MLOps Basics',ARRAY['Model deployment','API deployment','Docker','Environment variables','Git/GitHub','Cloud deployment concepts','Model monitoring','Performance monitoring','AI security basics']::text[],NULL,'Deploy an AI application using an API.',NULL,'Deploy and monitor an AI application responsibly.'),
(23,6,'End-to-End AI Capstone',ARRAY['Problem Definition','Data Collection','Data Processing','AI Model','Application Development','API Integration','Testing','Deployment']::text[],NULL,'Develop a complete AI project such as a career assistant, study assistant, resume analyzer, document chatbot, customer support assistant, recommendation system, voice assistant, or educational tutor.',NULL,'Complete an end-to-end AI project from problem definition to deployment.'),
(24,6,'Final AI Project & Career Preparation',ARRAY['Final project completion','Model/application testing','Performance optimization','Deployment','GitHub documentation','Project presentation','AI interview preparation','Python interview preparation','Machine Learning interview preparation','Generative AI interview preparation','Resume preparation','Portfolio development','Mock interview','Final evaluation','Certification']::text[],'Present and defend the deployed AI capstone.',NULL,NULL,'Graduate with a documented AI project, portfolio, interview practice, and certification.')
) AS v(week_number, month_number, title, topics, practical_task, assignment, mini_project, expected_outcome)
WHERE c.slug = 'artificial-intelligence'
ON CONFLICT (course_id, week_number) DO UPDATE SET
  month_number = EXCLUDED.month_number, title = EXCLUDED.title, topics = EXCLUDED.topics,
  practical_task = EXCLUDED.practical_task, assignment = EXCLUDED.assignment,
  mini_project = EXCLUDED.mini_project, expected_outcome = EXCLUDED.expected_outcome, updated_at = now();
